import{_ as i,o as n,c as a,ae as t}from"./chunks/framework.Dn6zxbF8.js";const g=JSON.parse('{"title":"Enforcing Named Bindings in Ecto Queries","description":"","frontmatter":{"id":"3519904902","title":"Enforcing Named Bindings in Ecto Queries","state":"Approved","created":"2024-08-21T00:00:00.000Z","tags":["ecto","elixir","sql"],"category":"Elixir"},"headers":[],"relativePath":"adrs/3519904902/README.md","filePath":"adrs/3519904902/README.md"}'),o={name:"adrs/3519904902/README.md"};function r(s,e,d,l,c,u){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="enforcing-named-bindings-in-ecto-queries" tabindex="-1">Enforcing Named Bindings in Ecto Queries <a class="header-anchor" href="#enforcing-named-bindings-in-ecto-queries" aria-label="Permalink to &quot;Enforcing Named Bindings in Ecto Queries&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Ecto allows the use of named bindings when composing queries. We will enforce named bindings across all queries in our codebase.</p><h3 id="clarity-and-readability" tabindex="-1">Clarity and Readability <a class="header-anchor" href="#clarity-and-readability" aria-label="Permalink to &quot;Clarity and Readability&quot;">​</a></h3><p>Named bindings indicate what each part of the query references, reducing confusion and increasing the code&#39;s maintainability.</p><h3 id="avoiding-errors" tabindex="-1">Avoiding Errors <a class="header-anchor" href="#avoiding-errors" aria-label="Permalink to &quot;Avoiding Errors&quot;">​</a></h3><p>When queries are combined, positional bindings can lead to operations being applied to the wrong entities, causing subtle bugs. Named bindings eliminate this risk by explicitly naming each binding.</p><h3 id="consistency" tabindex="-1">Consistency <a class="header-anchor" href="#consistency" aria-label="Permalink to &quot;Consistency&quot;">​</a></h3><p>Adopting a standard practice across the codebase simplifies onboarding and code reviews.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Refactoring Effort: Existing queries using positional bindings will need to be refactored to use named bindings.</li><li>Learning Curve: Developers need to get accustomed to consistently using named bindings.</li></ul><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>You <strong>MUST</strong> use named bindings in all Ecto queries except when impossible.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://hexdocs.pm/ecto/Ecto.Query.html#module-named-bindings" target="_blank" rel="noreferrer">Ecto Query Named Bindings</a></li></ul>',15)])])}const b=i(o,[["render",r]]);export{g as __pageData,b as default};
